void
backtrace(void)
{
  uint64 fp = r_fp();
  uint64 top = PGROUNDUP(fp);
  printf("backtrace:\n");
  while(fp < top && fp != 0){
    uint64 ra = *(uint64*)(fp - 8);
    uint64 prev = *(uint64*)(fp - 16);
    printf("%p\n", ra);
    if(prev <= fp)
      break;
    fp = prev;
  }
}
